import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def images(ctx):
    inputs = torch.rand((3, 4, 4), generator=ctx.rng.torch) * 255
    targets = torch.rand((3, 4, 4), generator=ctx.rng.torch) * 255
    lpips_distance = torch.tensor(float(int(ctx.index) % 4) / 10)
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets), "lpips_distance": synth.Tensor(lpips_distance)}
dataset = synth.Spec("hific-reconstruction", generator=images, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Reconstructor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=48, out_features=48)
    def forward(self, inputs):
        prediction = self.network(inputs.flatten(start_dim=1)).reshape(-1, 3, 4, 4)
        return {"prediction": prediction}
trainer = Trainer(Reconstructor(), train, recipe="structured-objective", recipe_config={"loss": "hific", "bindings": {"logits_or_prediction": {"output": "prediction"}, "targets": {"batch": "targets"}, "lpips_distance": {"batch": "lpips_distance"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
